import{_ as a,o as e,c as r,a2 as l}from"./chunks/framework.CFuv5BrO.js";const m=JSON.parse('{"title":"人工接管与审批","description":"Hearth Human Executor、审批卡、接管协议、人的错误输入与阶段映射。","frontmatter":{"title":"人工接管与审批","description":"Hearth Human Executor、审批卡、接管协议、人的错误输入与阶段映射。","outline":[2,3]},"headers":[],"relativePath":"architecture/human-takeover.md","filePath":"architecture/human-takeover.md","lastUpdated":null}'),i={name:"architecture/human-takeover.md"};function d(o,t,n,h,u,c){return e(),r("div",null,[...t[0]||(t[0]=[l('<p class="eyebrow">HUMAN TAKEOVER</p><h1 id="人工接管与审批" tabindex="-1">人工接管与审批 <a class="header-anchor" href="#人工接管与审批" aria-label="Permalink to &quot;人工接管与审批&quot;">​</a></h1><p class="lead">人不是失败后的补丁，而是执行系统的一等参与者。审批、接管和人的错误都必须被设计。</p><h2 id="human-executor-与接管" tabindex="-1">Human Executor 与接管 <a class="header-anchor" href="#human-executor-与接管" aria-label="Permalink to &quot;Human Executor 与接管&quot;">​</a></h2><p>人不是失败后的补丁，而是系统的一等执行器。</p><h3 id="审批卡" tabindex="-1">审批卡 <a class="header-anchor" href="#审批卡" aria-label="Permalink to &quot;审批卡&quot;">​</a></h3><p>审批必须让用户在十秒内判断：</p><ul><li>将要做什么；</li><li>使用哪个账户；</li><li>目标收件人/文件/仓库/日历/资源；</li><li>内容和附件；</li><li>可逆性；</li><li>失败和补偿方式；</li><li>审批有效期和范围。</li></ul><h3 id="接管协议" tabindex="-1">接管协议 <a class="header-anchor" href="#接管协议" aria-label="Permalink to &quot;接管协议&quot;">​</a></h3><ul><li>显示当前浏览器/桌面；</li><li>明确说明需要用户做什么；</li><li>暂停自动输入；</li><li>允许操作、批注和补充信息；</li><li>记录接管前后状态；</li><li>支持交还、缩小范围和终止。</li></ul><h3 id="人的错误也是输入" tabindex="-1">人的错误也是输入 <a class="header-anchor" href="#人的错误也是输入" aria-label="Permalink to &quot;人的错误也是输入&quot;">​</a></h3><p>用户拒绝、修改、撤销和接管不是噪声，而是评估和技能改进的重要样本；但不能把用户纠正自动变成更高权限。</p><h2 id="阶段映射" tabindex="-1">阶段映射 <a class="header-anchor" href="#阶段映射" aria-label="Permalink to &quot;阶段映射&quot;">​</a></h2><table tabindex="0"><thead><tr><th>执行器</th><th>首次出现</th></tr></thead><tbody><tr><td>Codex</td><td>Stage 1 / D1.2</td></tr><tr><td>Native（薄层）</td><td>Stage 1–2</td></tr><tr><td>Connector</td><td>Stage 2</td></tr><tr><td>Browser</td><td>Stage 2</td></tr><tr><td>Document/Data</td><td>Stage 2</td></tr><tr><td>GUI + Human 实时接管</td><td>Stage 3</td></tr><tr><td>手机接管入口</td><td>Stage 4</td></tr></tbody></table><p>Stage 0 只定义能力矩阵和 UI 契约；Stage 1 只用 Codex 证明一条真实纵向切片，不一次性接入所有执行器。</p>',15)])])}const p=a(i,[["render",d]]);export{m as __pageData,p as default};
